"use client";

import { useCallback, useMemo, useState } from "react";
import { Info } from "lucide-react";

import {
  ExperimentSidebar,
  type ExperimentKey,
} from "@/components/experiment-sidebar";
import { InterferometerDiagram } from "@/components/interferometer-diagram";
import { StaticExperimentDiagram } from "@/components/static-experiment-diagram";
import { StaticExperimentPanel } from "@/components/static-experiment-panel";
import { StatisticsPanel } from "@/components/statistics-panel";
import { SimulationControls } from "@/components/simulation-controls";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

interface ExperimentResult {
  id: number;
  live: boolean;
  exploded: boolean;
  safe: boolean;
  path: "A" | "B";
  timestamp: Date;
}

interface PhotonPath {
  id: number;
  path: "A" | "B";
  exploded?: boolean;
  safe?: boolean;
}

interface BombStatistics {
  totalExperiments: number;
  liveBombs: number;
  dummyBombs: number;
  safelyIdentified: number;
  exploded: number;
  detectorD2: number;
}

interface MachZehnderStatistics {
  totalExperiments: number;
  detectorA: number;
  detectorB: number;
  phaseShift: number;
  lastPath: "A" | "B" | null;
}

interface MichelsonMorleyStatistics {
  totalExperiments: number;
  constructive: number;
  destructive: number;
  armLengthDifference: number;
  lastPath: "A" | "B" | null;
}

const experimentContent: Record<
  ExperimentKey,
  {
    title: string;
    description: string;
  }
> = {
  "bomb-tester": {
    title: "Elitzur-Vaidman Bomb Tester",
    description:
      "A quantum mechanics thought experiment demonstrating interaction-free measurement. This interferometer can detect whether a bomb is live without detonating it.",
  },
  "mach-zehnder": {
    title: "Mach-Zehnder Interferometer",
    description:
      "A simple two-path interferometer that shows how beam splitters and mirrors recombine light into interference patterns.",
  },
  "michelson-morley": {
    title: "Michelson-Morley Interferometer",
    description:
      "A two-arm setup used to compare path lengths and observe how phase differences change the interference result at the detector.",
  },
};

export default function SimulationPage() {
  const [activeExperiment, setActiveExperiment] =
    useState<ExperimentKey>("bomb-tester");
  const [bombExperiments, setBombExperiments] = useState<ExperimentResult[]>([]);
  const [bombCurrentPath, setBombCurrentPath] = useState<PhotonPath | null>(null);
  const [machCurrentPath, setMachCurrentPath] = useState<PhotonPath | null>(null);
  const [michelsonCurrentPath, setMichelsonCurrentPath] =
    useState<PhotonPath | null>(null);
  const [isRunning, setIsRunning] = useState(false);
  const [batchCount, setBatchCount] = useState(100);
  const [phaseShift, setPhaseShift] = useState(1.57);
  const [armLengthDifference, setArmLengthDifference] = useState(100);
  const [connectionError, setConnectionError] = useState<string | null>(null);

  const [bombStats, setBombStats] = useState<BombStatistics>({
    totalExperiments: 0,
    liveBombs: 0,
    dummyBombs: 0,
    safelyIdentified: 0,
    exploded: 0,
    detectorD2: 0,
  });
  const [machStats, setMachStats] = useState<MachZehnderStatistics>({
    totalExperiments: 0,
    detectorA: 0,
    detectorB: 0,
    phaseShift: 1.57,
    lastPath: null,
  });
  const [michelsonStats, setMichelsonStats] =
    useState<MichelsonMorleyStatistics>({
      totalExperiments: 0,
      constructive: 0,
      destructive: 0,
      armLengthDifference: 0,
      lastPath: null,
    });

  const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8080";

  const runBombExperiment = useCallback(async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/simulation/run`);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      setConnectionError(null);

      return {
        id: bombExperiments.length + 1,
        live: data.live,
        exploded: data.exploded,
        safe: data.safe > 0,
        path: data.path,
        timestamp: new Date(),
      } satisfies ExperimentResult;
    } catch {
      setConnectionError(
        "Unable to connect to Spring Boot backend. Make sure it is running."
      );
      return null;
    }
  }, [API_BASE_URL, bombExperiments.length]);

  const runMachZehnderExperiment = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/api/simulation/mach-zehnder/run?phaseShift=${phaseShift}`
      );
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      setConnectionError(null);
      return (await response.json()) as {
        path: "A" | "B";
        detectorA: number;
        detectorB: number;
        phaseShift: number;
      };
    } catch {
      setConnectionError(
        "Unable to connect to Spring Boot backend. Make sure it is running."
      );
      return null;
    }
  }, [API_BASE_URL, phaseShift]);

  const runMichelsonMorleyExperiment = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/api/simulation/michelson-morley/run?armLengthDifference=${armLengthDifference}`
      );
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      setConnectionError(null);
      return (await response.json()) as {
        path: "A" | "B";
        constructive: number;
        destructive: number;
        armLengthDifference: number;
      };
    } catch {
      setConnectionError(
        "Unable to connect to Spring Boot backend. Make sure it is running."
      );
      return null;
    }
  }, [API_BASE_URL, armLengthDifference]);

  const updateBombStats = useCallback((result: ExperimentResult) => {
    setBombStats((prev) => ({
      totalExperiments: prev.totalExperiments + 1,
      liveBombs: prev.liveBombs + (result.live ? 1 : 0),
      dummyBombs: prev.dummyBombs + (result.live ? 0 : 1),
      safelyIdentified: prev.safelyIdentified + (result.safe ? 1 : 0),
      exploded: prev.exploded + (result.exploded ? 1 : 0),
      detectorD2:
        prev.detectorD2 + (!result.safe && !result.exploded ? 1 : 0),
    }));
  }, []);

  const handleRunSingle = useCallback(async () => {
    setIsRunning(true);

    if (activeExperiment === "bomb-tester") {
      const result = await runBombExperiment();
      if (result) {
        setBombCurrentPath({
          id: result.id,
          path: result.path,
          exploded: result.exploded,
          safe: result.safe,
        });

        setTimeout(() => {
          setBombExperiments((prev) => [...prev, result]);
          updateBombStats(result);
          setIsRunning(false);
        }, 1600);
        return;
      }
    } else if (activeExperiment === "mach-zehnder") {
      const result = await runMachZehnderExperiment();
      if (result) {
        setMachCurrentPath({
          id: machStats.totalExperiments + 1,
          path: result.path,
        });

        setTimeout(() => {
          setMachStats((prev) => ({
            totalExperiments: prev.totalExperiments + 1,
            detectorA: prev.detectorA + result.detectorA,
            detectorB: prev.detectorB + result.detectorB,
            phaseShift: result.phaseShift,
            lastPath: result.path,
          }));
          setIsRunning(false);
        }, 1600);
        return;
      }
    } else {
      const result = await runMichelsonMorleyExperiment();
      if (result) {
        setMichelsonCurrentPath({
          id: michelsonStats.totalExperiments + 1,
          path: result.path,
        });

        setTimeout(() => {
          setMichelsonStats((prev) => ({
            totalExperiments: prev.totalExperiments + 1,
            constructive: prev.constructive + result.constructive,
            destructive: prev.destructive + result.destructive,
            armLengthDifference: result.armLengthDifference,
            lastPath: result.path,
          }));
          setIsRunning(false);
        }, 1600);
        return;
      }
    }

    setIsRunning(false);
  }, [
    activeExperiment,
    machStats.totalExperiments,
    michelsonStats.totalExperiments,
    runBombExperiment,
    runMachZehnderExperiment,
    runMichelsonMorleyExperiment,
    updateBombStats,
  ]);

  const handleRunBatch = useCallback(
    async (count: number) => {
      setIsRunning(true);

      if (activeExperiment === "bomb-tester") {
        setBombCurrentPath(null);

        const newExperiments: ExperimentResult[] = [];
        for (let i = 0; i < count; i++) {
          const result = await runBombExperiment();
          if (!result) break;

          result.id = bombExperiments.length + newExperiments.length + 1;
          newExperiments.push(result);
          updateBombStats(result);

          if (i < count - 1) {
            await new Promise((resolve) => setTimeout(resolve, 50));
          }
        }

        setBombExperiments((prev) => [...prev, ...newExperiments]);
      } else if (activeExperiment === "mach-zehnder") {
        setMachCurrentPath(null);

        for (let i = 0; i < count; i++) {
          const result = await runMachZehnderExperiment();
          if (!result) break;

          setMachStats((prev) => ({
            totalExperiments: prev.totalExperiments + 1,
            detectorA: prev.detectorA + result.detectorA,
            detectorB: prev.detectorB + result.detectorB,
            phaseShift: result.phaseShift,
            lastPath: result.path,
          }));

          if (i === count - 1) {
            setMachCurrentPath({
              id: machStats.totalExperiments + i + 1,
              path: result.path,
            });
          }

          if (i < count - 1) {
            await new Promise((resolve) => setTimeout(resolve, 50));
          }
        }
      } else {
        setMichelsonCurrentPath(null);

        for (let i = 0; i < count; i++) {
          const result = await runMichelsonMorleyExperiment();
          if (!result) break;

          setMichelsonStats((prev) => ({
            totalExperiments: prev.totalExperiments + 1,
            constructive: prev.constructive + result.constructive,
            destructive: prev.destructive + result.destructive,
            armLengthDifference: result.armLengthDifference,
            lastPath: result.path,
          }));

          if (i === count - 1) {
            setMichelsonCurrentPath({
              id: michelsonStats.totalExperiments + i + 1,
              path: result.path,
            });
          }

          if (i < count - 1) {
            await new Promise((resolve) => setTimeout(resolve, 50));
          }
        }
      }

      setIsRunning(false);
    },
    [
      activeExperiment,
      bombExperiments.length,
      machStats.totalExperiments,
      michelsonStats.totalExperiments,
      runBombExperiment,
      runMachZehnderExperiment,
      runMichelsonMorleyExperiment,
      updateBombStats,
    ]
  );

  const handleReset = useCallback(() => {
    if (activeExperiment === "bomb-tester") {
      setBombExperiments([]);
      setBombCurrentPath(null);
      setBombStats({
        totalExperiments: 0,
        liveBombs: 0,
        dummyBombs: 0,
        safelyIdentified: 0,
        exploded: 0,
        detectorD2: 0,
      });
    } else if (activeExperiment === "mach-zehnder") {
      setMachCurrentPath(null);
        setMachStats({
          totalExperiments: 0,
          detectorA: 0,
          detectorB: 0,
          phaseShift,
          lastPath: null,
        });
    } else {
      setMichelsonCurrentPath(null);
      setMichelsonStats({
        totalExperiments: 0,
        constructive: 0,
        destructive: 0,
        armLengthDifference,
        lastPath: null,
      });
    }
  }, [activeExperiment, armLengthDifference, phaseShift]);

  const activeContent = useMemo(
    () => experimentContent[activeExperiment],
    [activeExperiment]
  );

  const isBombTester = activeExperiment === "bomb-tester";
  const activeAnimatedPath = isBombTester
    ? bombCurrentPath
    : activeExperiment === "mach-zehnder"
      ? machCurrentPath
      : michelsonCurrentPath;

  const machMetrics = useMemo(
    () => [
      { label: "Total Photons", value: machStats.totalExperiments },
      { label: "Bright Port (A)", value: machStats.detectorA, tone: "accent" as const },
      { label: "Dark Port (B)", value: machStats.detectorB },
      { label: "Phase Shift", value: machStats.phaseShift.toFixed(2) },
      {
        label: "Preferred Output",
        value:
          machStats.detectorA === machStats.detectorB
            ? "-"
            : machStats.detectorA > machStats.detectorB
              ? "A"
              : "B",
      },
      { label: "Last Detection", value: machStats.lastPath ?? "-" },
    ],
    [machStats]
  );

  const michelsonMetrics = useMemo(() => {
    const visibility =
      michelsonStats.totalExperiments > 0
        ? Math.abs(
            (michelsonStats.constructive - michelsonStats.destructive) /
              michelsonStats.totalExperiments
          ).toFixed(2)
        : "0.00";

    return [
      { label: "Total Photons", value: michelsonStats.totalExperiments },
      {
        label: "Bright Detector",
        value: michelsonStats.constructive,
        tone: "accent" as const,
      },
      {
        label: "Dark Output",
        value: michelsonStats.destructive,
        tone: "destructive" as const,
      },
      {
        label: "Arm Length Difference",
        value: michelsonStats.armLengthDifference,
        note: "nm",
      },
      { label: "Interference Visibility", value: visibility },
      { label: "Last Detection", value: michelsonStats.lastPath ?? "-" },
    ];
  }, [michelsonStats]);

  return (
    <main className="min-h-screen bg-background p-4 md:p-6 lg:p-8">
      <div className="mx-auto grid max-w-7xl gap-6 lg:grid-cols-[280px_minmax(0,1fr)]">
        <ExperimentSidebar
          activeExperiment={activeExperiment}
          onSelect={setActiveExperiment}
        />

        <div className="space-y-6">
          <header className="rounded-2xl border border-border bg-card p-6">
            <h1 className="text-2xl font-bold text-foreground md:text-3xl">
              {activeContent.title}
            </h1>
            <p className="mt-2 max-w-3xl text-muted-foreground">
              {activeContent.description}
            </p>
          </header>

          {connectionError && (
            <Alert variant="destructive">
              <div className="flex items-start gap-3">
                <Info className="mt-0.5 h-4 w-4 shrink-0" />
                <div>
                  <AlertTitle>Connection Error</AlertTitle>
                  <AlertDescription>{connectionError}</AlertDescription>
                </div>
              </div>
            </Alert>
          )}

          <div className="grid gap-6 xl:grid-cols-3">
            <div className="xl:col-span-2">
              {isBombTester ? (
                <Card>
                  <CardHeader className="pb-3">
                    <CardTitle className="text-base font-semibold">
                      Interferometer Diagram
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <InterferometerDiagram
                      currentPath={bombCurrentPath}
                      isRunning={isRunning}
                    />
                  </CardContent>
                </Card>
              ) : (
                <StaticExperimentDiagram
                  experiment={activeExperiment}
                  currentPath={activeAnimatedPath}
                  isRunning={isRunning}
                />
              )}
            </div>

            <div className="space-y-6">
              {isBombTester ? (
                <>
                  <SimulationControls
                    onRunSingle={handleRunSingle}
                    onRunBatch={handleRunBatch}
                    onReset={handleReset}
                    isRunning={isRunning}
                    batchCount={batchCount}
                    onBatchCountChange={setBatchCount}
                  />
                  <StatisticsPanel stats={bombStats} />
                </>
              ) : (
                <StaticExperimentPanel
                  experiment={activeExperiment}
                  onRunSingle={handleRunSingle}
                  onRunBatch={handleRunBatch}
                  onReset={handleReset}
                  isRunning={isRunning}
                  batchCount={batchCount}
                  onBatchCountChange={setBatchCount}
                  phaseShift={phaseShift}
                  onPhaseShiftChange={(value) => {
                    setPhaseShift(value);
                    setMachStats({
                      totalExperiments: 0,
                      detectorA: 0,
                      detectorB: 0,
                      phaseShift: value,
                      lastPath: null,
                    });
                    setMachCurrentPath(null);
                  }}
                  armLengthDifference={armLengthDifference}
                  onArmLengthDifferenceChange={(value) => {
                    setArmLengthDifference(value);
                    setMichelsonStats({
                      totalExperiments: 0,
                      constructive: 0,
                      destructive: 0,
                      armLengthDifference: value,
                      lastPath: null,
                    });
                    setMichelsonCurrentPath(null);
                  }}
                  metrics={
                    activeExperiment === "mach-zehnder"
                      ? machMetrics
                      : michelsonMetrics
                  }
                />
              )}
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
